#!/bin/bash
# room-machine installer. Exits 0 immediately unless ROOM_MACHINE_ENABLED=1.
# The payload below is the machine/ tree at this commit, so
# `bash -c "$(curl -fsSL <this file>)"` can run without a git checkout.
#
# Integrity note (M7): PAYLOAD_SHA256 below guards the embedded payload
# against truncation only — it is self-referential and does NOT authenticate
# this script against substitution. Verify this script out-of-band before
# running it (see machine/README.md). When this script runs from a file and
# ROOM_MACHINE_INSTALL_SHA256 is set, it verifies its own bytes first and
# refuses to run on mismatch.
set -euo pipefail

PAYLOAD_SHA256="4c4f2541193f40414f14598368831964a523727329a1a3713e4e0cdab7daa3d8"
PAYLOAD_B64=""

if [ "${ROOM_MACHINE_ENABLED:-}" != "1" ]; then
  echo "room-machine is off. Set ROOM_MACHINE_ENABLED=1 to install."
  exit 0
fi

NODE="${ROOM_MACHINE_NODE:-node}"
if ! command -v "$NODE" >/dev/null 2>&1; then
  echo "Node.js 24.19 or newer is required."
  exit 1
fi
NODE_BIN=$(command -v "$NODE")
NODE_MAJOR=$("$NODE_BIN" -p "Number(process.versions.node.split('.')[0])")
NODE_MINOR=$("$NODE_BIN" -p "Number(process.versions.node.split('.')[1])")
if [ "$NODE_MAJOR" -lt 24 ] || { [ "$NODE_MAJOR" -eq 24 ] && [ "$NODE_MINOR" -lt 19 ]; }; then
  echo "Node.js 24.19 or newer is required (found $("$NODE_BIN" -v))."
  exit 1
fi

sha256_file() {
  if command -v sha256sum >/dev/null 2>&1; then
    sha256sum "$1" | awk '{print $1}'
  else
    shasum -a 256 "$1" | awk '{print $1}'
  fi
}

script_dir=""
if [ -n "${BASH_SOURCE[0]:-}" ] && [ -f "${BASH_SOURCE[0]}" ]; then
  script_dir=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
fi

# M7: optional out-of-band authentication of this script. Set
# ROOM_MACHINE_INSTALL_SHA256 to the expected sha256 of install.sh (taken
# from the release notes, not from the script itself) before running from a
# downloaded file. Refuses to run on mismatch.
if [ -n "${ROOM_MACHINE_INSTALL_SHA256:-}" ] && [ -n "${BASH_SOURCE[0]:-}" ] && [ -f "${BASH_SOURCE[0]}" ]; then
  actual="$(sha256_file "${BASH_SOURCE[0]}")"
  if [ "$actual" != "$ROOM_MACHINE_INSTALL_SHA256" ]; then
    echo "install.sh failed its out-of-band integrity check; refusing to run." >&2
    exit 1
  fi
fi

if [ -n "$script_dir" ] && [ -f "$script_dir/bin/room-machine.mjs" ]; then
  APP=$(cd "$script_dir/.." && pwd)
else
  if [ -z "$PAYLOAD_SHA256" ] || [ -z "$PAYLOAD_B64" ]; then
    echo "refusing to extract: payload sha256 is empty"
    exit 1
  fi
  DEST="${ROOM_MACHINE_PREFIX:-$HOME/.local/share/room-machine-app}"
  mkdir -p "$DEST"
  tmp=$(mktemp)
  printf '%s' "$PAYLOAD_B64" | "$NODE_BIN" --input-type=module -e 'import { writeFileSync } from "node:fs"; const chunks=[]; for await (const chunk of process.stdin) chunks.push(chunk); writeFileSync(process.argv[1], Buffer.from(Buffer.concat(chunks).toString("utf8"), "base64"));' "$tmp"
  got=$(sha256_file "$tmp")
  if [ "$got" != "$PAYLOAD_SHA256" ]; then
    echo "payload sha256 mismatch"
    rm -f "$tmp"
    exit 1
  fi
  tar -xzf "$tmp" -C "$DEST"
  rm -f "$tmp"
  APP="$DEST"
fi

if [ "$(uname)" = "Darwin" ]; then
  DEFAULT_HOME="$HOME/Library/Application Support/room-machine"
else
  DEFAULT_HOME="$HOME/.local/share/room-machine"
fi
export ROOM_MACHINE_ENABLED=1
export ROOM_MACHINE_HOME="${ROOM_MACHINE_HOME:-$DEFAULT_HOME}"
mkdir -p "$ROOM_MACHINE_HOME"
BIN="$APP/machine/bin/room-machine.mjs"

pre=$("$NODE_BIN" "$BIN" preflight)
printf '%s\n' "$pre"
ok=$(printf '%s' "$pre" | "$NODE_BIN" --input-type=module -e 'let text=""; for await (const chunk of process.stdin) text += chunk; const parsed = JSON.parse(text); process.stdout.write(parsed.ok ? "yes" : "no");')
if [ "$ok" != "yes" ]; then
  exit 1
fi

sudo env ROOM_MACHINE_ENABLED=1 ROOM_MACHINE_HOME="$ROOM_MACHINE_HOME" PATH="$PATH" "$NODE_BIN" "$BIN" apply-system

if [ "$(uname)" = "Darwin" ] && [ "$(uname -m)" = "arm64" ]; then
  mkdir -p "$ROOM_MACHINE_HOME/bin"
  while IFS="$(printf '\t')" read -r name url sha; do
    if [ -z "$sha" ]; then
      echo "refusing ${name}: empty sha256"
      exit 1
    fi
    tar_path="$ROOM_MACHINE_HOME/${name}.tar.gz"
    curl -fsSL "$url" -o "$tar_path"
    got=$(sha256_file "$tar_path")
    if [ "$got" != "$sha" ]; then
      echo "${name} sha256 mismatch"
      exit 1
    fi
    tar -xzf "$tar_path" -C "$ROOM_MACHINE_HOME/bin"
  done < <("$NODE_BIN" --input-type=module -e 'import { readFileSync } from "node:fs"; const versions = JSON.parse(readFileSync(process.argv[1], "utf8")); for (const name of ["lume", "driver"]) { const pin = versions[name]; process.stdout.write(`${name}\t${pin.url}\t${pin.sha256}\n`); }' "$APP/machine/versions.json")
fi

code=""
while [ $# -gt 0 ]; do
  case "$1" in
    --enroll)
      code="${2:-}"
      shift 2
      ;;
    *)
      shift
      ;;
  esac
done
if [ -z "$code" ]; then
  echo "Install reached enroll with no --enroll code."
  exit 1
fi

# L5: the one-time code travels via stdin, never argv (ps-visible).
printf %s "$code" | "$NODE_BIN" "$BIN" enroll
"$NODE_BIN" "$BIN" prepare-golden >"$ROOM_MACHINE_HOME/golden.log" 2>&1 &

if [ "$(uname)" = "Darwin" ]; then
  agents="$HOME/Library/LaunchAgents"
  mkdir -p "$agents"
  path_value="$ROOM_MACHINE_HOME/bin:/usr/bin:/bin:/usr/sbin:/sbin"
  sed \
    -e "s|__APP__|$APP|g" \
    -e "s|__HOME__|$ROOM_MACHINE_HOME|g" \
    -e "s|__PATH__|$path_value|g" \
    "$APP/machine/launchd/com.uuriko.room-machine.plist" \
    >"$agents/com.uuriko.room-machine.plist"
  launchctl bootout "gui/$(id -u)/com.uuriko.room-machine" >/dev/null 2>&1 || true
  launchctl bootstrap "gui/$(id -u)" "$agents/com.uuriko.room-machine.plist"
fi

"$NODE_BIN" "$BIN" doctor
echo "room-machine stop"
echo "room-machine pause --minutes N"
echo "room-machine uninstall"
